const body = $input.first().json.body || $input.first().json;
const required = ["nom","site_web","secteur","ville"];
for (const f of required) if (!body[f]) throw new Error("Champ manquant: "+f);
let url = body.site_web.trim();
if (!url.startsWith("http")) url = "https://" + url;
url = url.replace(/\/$/,"");
return [{ json: { nom: body.nom.trim(), site_web: url, secteur: body.secteur.toLowerCase().trim(), ville: body.ville.trim(), email: body.email || null, pipeline_id: "gn_"+Date.now()+"_"+Math.random().toString(36).substr(2,6), started_at: new Date().toISOString(), retry_state: { stratege: 0, architecte: 0, copywriter: 0, max: 2 } } }];

const prospect = $("✅ Init").first().json;
const scan = $input.first().json;
const BLACKLIST = ["facebook.com","amazon.","google.com","apple.com","microsoft.com","booking.com","tripadvisor"];
if (!scan.status || scan.status >= 400) return [{ json: { brain_go: false, brain_reason: "Site inaccessible HTTP "+scan.status, prospect, scan } }];
if (scan.ttfb > 9000) return [{ json: { brain_go: false, brain_reason: "TTFB mort", prospect, scan } }];
if (BLACKLIST.some(b => prospect.site_web.includes(b))) return [{ json: { brain_go: false, brain_reason: "Blackliste", prospect, scan } }];
const brain_context = JSON.stringify({ prospect: { nom: prospect.nom, site: prospect.site_web, secteur: prospect.secteur, ville: prospect.ville }, signals: { ttfb_ms: scan.ttfb, http_status: scan.status, title: scan.title || "ABSENT", h1: scan.h1 || "ABSENT", meta_desc: scan.meta_desc ? "presente ("+scan.meta_desc.length+" chars)" : "ABSENTE", ville_dans_title: (scan.title||"").toLowerCase().includes(prospect.ville.toLowerCase()) } });
return [{ json: { brain_go: true, brain_context, prospect, scan, retry_state: prospect.retry_state } }];

const raw = $input.first().json;
const content = raw.content?.[0]?.text || "{}";
let parsed;
try { parsed = JSON.parse(content); } catch(e) { parsed = { decision:"GO", confidence:50, top_angles:["Performance","SEO Local"], probleme_critique:"Site non optimise", ton_optimal:"consultant_expert", brain_reasoning:"Fallback", priorite:"moyenne", seuil_qualite_minimum:65, agent_instructions:{stratege:"Focus ROI",architecte:"Mobile-first",copywriter:"Direct"} }; }
return [{ json: { brain_decision_1: parsed, brain_go: parsed.decision==="GO", prospect: $("🧠 Brain Pré-analyse").first().json.prospect, scan: $("🧠 Brain Pré-analyse").first().json.scan, retry_state: $("✅ Init").first().json.retry_state } }];

